"""Check selected states in VWF files generated by Quartus Simulator."""

import re
from pathlib import Path


HERE = Path(__file__).resolve().parent
STEP_NS = 1_000_000


def signal_events(content, name):
    match = re.search(r'TRANSITION_LIST\("' + re.escape(name) + r'"\)\s*\{', content)
    if not match:
        raise AssertionError(f"missing {name}")
    start = match.end()
    depth = 1
    end = start
    while depth:
        depth += (content[end] == "{") - (content[end] == "}")
        end += 1
    block = content[start:end - 1]
    tokens = re.findall(r'NODE|REPEAT\s*=\s*\d+|LEVEL\s+[01XUZ]\s+FOR\s+[\d.]+|[{}]', block)
    pos = [0]

    def parse_node():
        assert tokens[pos[0]] == "NODE"
        pos[0] += 1
        assert tokens[pos[0]] == "{"
        pos[0] += 1
        repeat = 1
        events = []
        while tokens[pos[0]] != "}":
            token = tokens[pos[0]]
            if token.startswith("REPEAT"):
                repeat = int(re.search(r"\d+", token).group())
                pos[0] += 1
            elif token == "NODE":
                events.extend(parse_node())
            else:
                level, duration = re.search(
                    r"LEVEL\s+([01XUZ])\s+FOR\s+([\d.]+)", token).groups()
                events.append((level, int(float(duration))))
                pos[0] += 1
        pos[0] += 1
        return events * repeat

    return parse_node()


def value_at(events, time_ns):
    elapsed = 0
    for level, duration in events:
        elapsed += duration
        if time_ns < elapsed:
            assert level in ("0", "1"), (level, time_ns)
            return int(level)
    raise AssertionError(f"time {time_ns} exceeds VWF duration")


def bus_at(content, name, width, time_ns):
    return sum(
        value_at(signal_events(content, f"{name}[{bit}]"), time_ns) << bit
        for bit in range(width)
    )


def rising_edges(events):
    elapsed = 0
    edges = []
    prior = "0"
    for level, duration in events:
        if level == "1" and prior != "1":
            edges.append(elapsed)
        elapsed += duration
        prior = level
    return edges


def cycle_values(content, count):
    # The first cycle starts at 3.5 us, each following cycle after 500
    # accelerated tick pulses.  Sample well after the start edge.
    values = []
    for cycle in range(count):
        instant = 10_000 + cycle * STEP_NS
        values.append((
            bus_at(content, "scan_index", 6, instant),
            bus_at(content, "target_index", 6, instant),
            value_at(signal_events(content, "target_valid"), instant),
            bus_at(content, "mode_code", 2, instant),
        ))
    return values


def main():
    lock = (HERE / "target_tracker_lock_result.vwf").read_text(encoding="utf-8")
    rows = cycle_values(lock, 22)
    expected_angles = [
        0, 1, 1, 1, 0, 2, 0, 1, 0, 1, 2, 2,
        2, 1, 3, 0, 4, 5, 6, 7, 8, 9,
    ]
    assert [row[0] for row in rows] == expected_angles, rows
    assert rows[2][3] == 0 and rows[3][3] == 1, rows[2:4]
    assert rows[6][1] == 0 and rows[6][2] == 1, rows[6]
    assert rows[10][3] == 2 and rows[11][3] == 2, rows[10:12]
    assert rows[12][1] == 2 and rows[12][3] == 1, rows[12]
    assert rows[21][3] == 0 and rows[21][2] == 0, rows[21]

    edge = (HERE / "target_tracker_edge_result.vwf").read_text(encoding="utf-8")
    edge_rows = cycle_values(edge, 41)
    assert [r[0] for r in edge_rows[:37]] == list(range(37))
    assert edge_rows[37][0] == 36 and edge_rows[38][1] == 36
    assert edge_rows[39][0] == 35 and edge_rows[40][1] == 35
    assert all(0 <= r[0] <= 36 for r in rows + edge_rows)

    flow = (HERE / "tracking_flow_result.vwf").read_text(encoding="utf-8")
    cycles = rising_edges(signal_events(flow, "cycle_start"))
    starts = rising_edges(signal_events(flow, "ultra_start"))
    results = rising_edges(signal_events(flow, "result_done"))
    assert len(cycles) == 3 and len(starts) == 9 and len(results) == 3
    assert all(b - a >= 1_000_000 for a, b in zip(cycles, cycles[1:]))
    for cycle in range(3):
        start = cycles[cycle]
        sample_starts = starts[cycle * 3:cycle * 3 + 3]
        assert all(start + 260_000 <= t < results[cycle] for t in sample_starts)
        assert all(value_at(signal_events(flow, "servo_quiet"), t) == 1
                   for t in sample_starts)
        assert value_at(signal_events(flow, "servo_quiet"), start + 50_000) == 0
        assert value_at(signal_events(flow, "servo_quiet"), start + 180_000) == 1
    assert [bus_at(flow, "filtered_distance", 12, t + 1_000)
            for t in results] == [150, 82, 91]
    assert [bus_at(flow, "scan_index", 6, t + 10_000)
            for t in cycles] == [0, 1, 1]
    assert bus_at(flow, "mode_code", 2, results[-1] + 10_000) == 1
    servo = (HERE / "tracking_servo_result.vwf").read_text(encoding="utf-8")
    anchors = [480, 880, 1380, 1880, 2340]
    assert [bus_at(servo, "pulse_width_us", 12, 10_000 + i * 20_000_000)
            for i in range(5)] == anchors
    pwm_events = signal_events(servo, "pwm_out")
    high_lengths = [duration for level, duration in pwm_events if level == "1"]
    assert len(high_lengths) == 5
    assert all(abs(actual - expected * 1000) <= 500
               for actual, expected in zip(high_lengths, anchors))
    print("Quartus VWF checks passed: 100/120 mm boundaries, invalid echo, "
          "local follow, recovery, 180-degree edge, servo quiet time, "
          "three-sample median, calibrated PWM, and result-gated angle changes")


if __name__ == "__main__":
    main()
